"""Write the agent graph's Mermaid diagram to docs/graph.md.

Usage: python scripts/draw_graph.py [--output docs/graph.md]
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from app.graph import mermaid_diagram

DEFAULT_OUTPUT = Path(__file__).resolve().parent.parent / "docs" / "graph.md"


def render() -> str:
    """The full Markdown page: a heading, one sentence, and the diagram."""
    return (
        "# Agent graph\n\n"
        "Generated by `python scripts/draw_graph.py` from `app/graph.py`. "
        "Dotted arrows are the conditional edges chosen by `route_after_critique`.\n\n"
        f"```mermaid\n{mermaid_diagram().strip()}\n```\n"
    )


def parse_args(argv: list[str] | None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--output", type=Path, default=DEFAULT_OUTPUT, help="Markdown file to write"
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(render())
    print(f"Wrote {args.output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
